R=Path(__file__).resolve().parents[1];B=R/'bench/reviews/tee-fit-v5-spectra';D=R/'docs/gallery/key-fan';TAG='tee-fit-v5-2026-10-09';REL=f'https://github.com/thereprocase/peg/releases/download/{TAG}/';BUNDLE='tee-fit-v5__native-source-and-checks.zip'
def receipt(p):return dict(sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size)
