 for name in meshes:shutil.copyfile(B/name,dst/name)
 (dst/'checks.json').write_text(json.dumps(report,indent=2)+'\n')
 links=' · '.join(f'<a href="fit-v5/HX05-fit-v5-{size}mm__rack-angle__print.stl" download>{size} mm coupon STL</a>' for size in (3,5,7))
 rows=''.join(f'<tr><td>{letter}</td><td>{2*c:.2f} mm</td><td>{3+2*c:.2f} mm</td><td>{5+2*c:.2f} mm</td><td>{7+2*c:.2f} mm</td></tr>' for letter,c in zip('ABCDE',(.10,.15,.19,.23,.28)))
 section=f'''<!-- FIT_V5_BEGIN --><section id="fit-coupon-v5"><h2>Fit spectrum v5: pick one letter per size</h2><p>Three connected coupons for <strong>3, 5 and 7 mm hexes</strong>, each with <strong>five slots A–E</strong>, engraved with size and letter. C uses the latest requested clearance: 0.38 mm total across flats. Each square 3 mm floor has a 1 mm through vent.</p><p><strong><a href="fit-v5/{meshes[0]}" download>Download all three spectra on one plate</a></strong><br>{links}<br><a href="{REL}HX05-fit-v5.FCStd">FreeCAD</a> · <a href="{REL}HX05-fit-v5__three-spectra__print.step">STEP</a> · <a href="{REL}{BUNDLE}">CAD, adjustable source and checks ZIP</a></p><model-viewer id="fit-spectrum-viewer" src="fit-v5/coupon.glb" camera-controls camera-orbit="65deg 65deg auto" interaction-prompt="none" alt="Three connected coupons with five lettered hex slots each" style="height:380px"></model-viewer><table><thead><tr><th>Letter</th><th>Total AF clearance</th><th>3 mm bore AF</th><th>5 mm bore AF</th><th>7 mm bore AF</th></tr></thead><tbody>{rows}</tbody></table><h3>Print at the rack angles</h3><p>Keep the supplied flat bases on the bed; do not auto-orient these models. Shafts lie horizontally, matching the rack’s left-end print. The 3 mm coupon uses the lower-tier 90° grip turn; the 5 mm coupon uses the upper-tier 65° turn. The 7 mm coupon uses the upper-tier angle as a trial: 7 mm is not in the documented Bondhus 13189 set. All three have the rack’s 20° heading on the bed. These angles preserve the six-flat bore orientation relative to the layers; no roof enlargement is applied.</p><p>Shaft guides are 40 mm for 3 and 5 mm, and 56 mm for 7 mm, plus a separate 0.8 mm entrance. Change <code>--angle-3</code>, <code>--angle-5</code>, <code>--angle-7</code> or <code>--heading</code> when rebuilding the source to try other orientations. FreeCAD properties record build dimensions; editing metadata alone does not rebuild the model.</p><h3>Pick the letters after printing</h3><p>Use the same printer, filament and calibrated compensation as the rack. Inspect the horizontal bore roofs, vent paths and supports in your actual slicer. Starting at E, try each slot down toward A and select the smallest clearance that seats fully to the floor and slides out comfortably, without forcing or binding. Compare rocking and rotational play. Report <strong>3 mm = _, 5 mm = _, 7 mm = _</strong>. The loose 3E bore permits full rotation geometrically; do not choose it when a rotational stop is required.</p><p>Native solids, nominal insertion, vent openings, retained stop shoulders and mesh/STEP/FreeCAD exports pass <a href="fit-v5/checks.json">the geometry checks</a>. Slicing and physical fit remain pending; no overnight job has been submitted from this box, which has no configured printer connector or local owner-profile slicer. No G-code is supplied.</p><p>Earlier coupons: <a href="https://github.com/thereprocase/peg/releases/tag/tee-fit-v4-2026-10-09">vented v4</a> · <a href="https://github.com/thereprocase/peg/releases/tag/tee-fit-v3-2026-10-09">snug v3</a>. The archived full rack below retains its earlier seats.</p></section><!-- FIT_V5_END -->'''
 p=D/'index.html';text=p.read_text();text=re.sub(r'<!-- FIT_V[345]_BEGIN -->.*?<!-- FIT_V[345]_END -->','',text,flags=re.S)
 header='<header><nav><a href="../../">Product groups</a><a href="../current-pegs/?family=repro">Repro collection</a></nav><h1>Hex fit spectra</h1><p>Three sizes, five lettered fits per size, in rack print orientations.</p><p class="status">Fit coupon v5 · native geometry checked; slicing and physical selection pending.</p></header>'
 text=re.sub(r'<header>.*?</header>',header+section,text,count=1,flags=re.S);p.write_text(text)
