 p=R/'docs/gallery/current-pegs/catalog.json';d=json.loads(p.read_text());q=next(q for q in d['parts'] if q['id']=='HX04');q['notes']['status']='Socket fit spectrum · new coupon v5';q['notes']['qualification']='Five lettered fits for each of 3, 5 and 7 mm, with vented floors and rack print angles. Physical fit selection and slicing pending. Archived full rack retains earlier seats.';q['extra_downloads']=[dict(label='Three five-slot fit spectra and archived HX04 rack',url='../key-fan/?v=5#fit-coupon-v5')];p.write_text(json.dumps(d,indent=2)+'\n')
 p=R/'publication/current-pegs-v1-additions.json';d=json.loads(p.read_text());d['catalog.json']=receipt(R/'docs/gallery/current-pegs/catalog.json');p.write_text(json.dumps(d,indent=2)+'\n')
 (R/'publication/key-fan-v2-additions.json').write_text(json.dumps({q.name:receipt(q) for q in sorted(D.iterdir()) if q.is_file() and q.name!='part-hx04__v1__left-cheek__fit-pf02c9-hoop5__print.stl'},indent=2)+'\n')
 (R/'publication/tee-fit-v5-page-additions.json').write_text(json.dumps({q.relative_to(R).as_posix():receipt(q) for q in dst.iterdir()},indent=2)+'\n')
 out.mkdir(parents=True,exist_ok=True)
 src=R/'bench/source/tee_racks_v1';paths=[src/'fit_spectrum_v5.py',src/'fonts/Fillaprint-Regular.ttf',src/'fonts/OFL.txt',src/'tools/setup_freecad_linux.sh',src/'tools/check_fit_spectrum.py']+[p for p in B.iterdir() if p.suffix in ('.stl','.step','.FCStd','.json','.md')]
 entries={p.relative_to(R).as_posix():p.read_bytes() for p in paths};entries['MANIFEST.json']=(json.dumps({name:dict(sha256=hashlib.sha256(data).hexdigest(),bytes=len(data)) for name,data in entries.items()},indent=2)+'\n').encode()
 with zipfile.ZipFile(out/BUNDLE,'w',zipfile.ZIP_DEFLATED) as z:
  for name,data in sorted(entries.items()):z.writestr(name,data)
