 p.write_text(json.dumps(assets,indent=2)+'\n');dpath.write_text(json.dumps(downloads,indent=2)+'\n')
 p=R/'docs/gallery/release-downloads.js';before,tail=p.read_text().split('const links=',1);_,end=json.JSONDecoder().raw_decode(tail);p.write_text(before+'const links='+json.dumps(downloads,separators=(',',':'))+tail[end:])
